class Solution {
    int memo[1 << 15][15];

public:
    int maximumCost(int n, vector<vector<int>>& highways, int k) {
        if (k >= n) return -1;
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& h : highways) {
            adj[h[0]].push_back({h[1], h[2]});
            adj[h[1]].push_back({h[0], h[2]});
        }
        memset(memo, -1, sizeof(memo));

        auto dfs = [&](auto& self, int mask, int u, int hops) -> int {
            if (hops == 0) return 0;
            if (memo[mask][u] != -1) return memo[mask][u];
            int res = -2;
            for (const auto& [v, w] : adj[u]) {
                if (!((mask >> v) & 1)) {
                    int sub = self(self, mask | (1 << v), v, hops - 1);
                    if (sub != -2) {
                        res = max(res, w + sub);
                    }
                }
            }
            return memo[mask][u] = res;
        };

        int ans = -1;
        for (int i = 0; i < n; i++) {
            memset(memo, -1, sizeof(memo));
            int val = dfs(dfs, 1 << i, i, k);
            if (val > ans) ans = val;
        }
        return ans;
    }
};

class Solution {
    private int[][] memo;

    public int maximumCost(int n, int[][] highways, int k) {
        if (k >= n) return -1;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] h : highways) {
            adj.get(h[0]).add(new int[]{h[1], h[2]});
            adj.get(h[1]).add(new int[]{h[0], h[2]});
        }

        int ans = -1;
        for (int i = 0; i < n; i++) {
            memo = new int[1 << n][n];
            for (int[] row : memo) Arrays.fill(row, -1);
            int val = dfs(1 << i, i, k, adj);
            if (val > ans) ans = val;
        }
        return ans;
    }

    private int dfs(int mask, int u, int hops, List<List<int[]>> adj) {
        if (hops == 0) return 0;
        if (memo[mask][u] != -1) return memo[mask][u];
        int res = -2;
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (((mask >> v) & 1) == 0) {
                int sub = dfs(mask | (1 << v), v, hops - 1, adj);
                if (sub != -2) {
                    res = Math.max(res, w + sub);
                }
            }
        }
        return memo[mask][u] = res;
    }
}

