var maximumCost = function(n, highways, k) {
    if (k >= n) return -1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of highways) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const memo = new Map();
    function dfs(mask, u, hops) {
        if (hops === 0) return 0;
        const key = (mask * 16 + u) * 16 + hops;
        if (memo.has(key)) return memo.get(key);
        let res = -Infinity;
        for (const [v, w] of adj[u]) {
            if (!((mask >> v) & 1)) {
                res = Math.max(res, w + dfs(mask | (1 << v), v, hops - 1));
            }
        }
        memo.set(key, res);
        return res;
    }
    let ans = -1;
    for (let i = 0; i < n; i++) {
        const val = dfs(1 << i, i, k);
        if (val > ans) ans = val;
    }
    return ans;
};
